def asal_bolenler(n):
    s, p = set(), 2
    while p*p <= n:
        while n % p == 0:
            s.add(p); n //= p
        p += 1
    if n > 1: s.add(n)
    return sorted(s)

def obeb(a, b):
    while b: a, b = b, a % b
    return a

def tam_periyot(a, c, m):
    if obeb(c, m) != 1:
        return False, 'c ile m aralarinda asal degil'
    for q in asal_bolenler(m):
        if (a - 1) % q != 0:
            return False, 'a-1, %d ile bolunmuyor' % q
    if m % 4 == 0 and (a - 1) % 4 != 0:
        return False, 'm 4e bolunuyor, a-1 bolunmuyor'
    return True, 'tam periyot (m = %d)' % m

def periyot(a, c, m, x0):
    g, x, i = {}, x0, 0
    while x not in g:
        g[x] = i; x = (a*x + c) % m; i += 1
    return i - g[x]

for a, c, m in ((5, 3, 16), (17, 43, 100), (6, 7, 12)):
    ok, neden = tam_periyot(a, c, m)
    print('a=%-3d c=%-3d m=%-4d -> %-5s %-34s gercek periyot (x0=1): %d'
          % (a, c, m, ok, neden, periyot(a, c, m, 1)))

