def hareketli(s, w):
    """2w+1 noktali hareketli ortalama; kenarlarda hesaplanamaz."""
    out = []
    for i in range(len(s)):
        if i < w or i >= len(s) - w:
            out.append(None)
        else:
            out.append(round(sum(s[i-w:i+w+1]) / (2*w + 1), 4))
    return out

