import math

M = 2**31 - 1
def lcg(s):
    x = s
    while True:
        x = (16807 * x) % M
        yield x / M

def kosum(ua, u1, u2, lam, mu, erlang, d):
    """Lindley. erlang=0 -> ustel servis, 1 -> Erlang-2 (ayni ortalama)."""
    W = [0.0]
    def servis(i):
        if erlang:
            return -(math.log(1 - u1[i]) + math.log(1 - u2[i])) / (2 * mu)
        return -math.log(1 - u1[i]) / mu
    S = servis(0)
    for i in range(1, len(ua)):
        A = -math.log(1 - ua[i]) / lam
        W.append(max(0.0, W[-1] + S - A))
        S = servis(i)
    return sum(W[d:]) / (len(W) - d)

