def etki(*isaret):
    """isaret: her faktor icin +1/-1/0 (0 = o faktor kontrast disinda)."""
    top = 0.0
    for a in (0, 1):
        for b in (0, 1):
            for c in (0, 1):
                w = 1
                for lvl, s in zip((a, b, c), isaret):
                    if s:
                        w *= s * (1 if lvl else -1)
                top += w * y[(a, b, c)]
    return top / 4

